<?php $page_title='Food Management'; include 'includes/header.php'; $foods=$pdo->query('SELECT f.*,c.category_name FROM foods f JOIN categories c ON c.id=f.category_id ORDER BY f.id DESC')->fetchAll(); ?><section class="page-banner"><div class="container"><div class="section-head"><div><div class="eyebrow">Menu catalogue</div><h1>Foods</h1></div><a class="button" href="add_food.php">Add Food</a></div></div></section><section class="section"><div class="container"><div class="food-grid"><?php foreach($foods as $food): ?><article class="food-card"><img src="<?= preg_match('/^https?:\/\//', $food['image']) ? esc($food['image']) : '../' . esc($food['image']) ?>" alt="<?= esc($food['food_name']) ?>"><div class="food-info"><h3><?= esc($food['food_name']) ?></h3><p><?= esc($food['category_name']) ?> &middot; ₹<?= number_format($food['price'],2) ?><br><span class="availability <?= $food['availability']?'':'off' ?>"><?= $food['availability']?'Available':'Unavailable' ?></span></p><a class="button secondary small" href="edit_food.php?id=<?= $food['id'] ?>">Edit</a> <a class="button small" href="delete_food.php?id=<?= $food['id'] ?>" onclick="return confirm('Delete this food?')">Delete</a></div></article><?php endforeach; ?></div></div></section><?php include 'includes/footer.php'; ?>